import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";import"./chunks/assets.NJs4UO-Q.js";var i=JSON.parse(`{"title":"核心操作","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code-for-vscode/core-operations.md","filePath":"zh/kimi-code-for-vscode/core-operations.md"}`),a={name:`kimi-code-for-vscode/core-operations.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="核心操作" tabindex="-1">核心操作 <a class="header-anchor" href="#核心操作" aria-label="Permalink to “核心操作”">​</a></h1><div class="warning custom-block"><p class="custom-block-title">VS Code 插件适配中</p><p>Kimi Code for VS Code 目前仅对旧版 Python CLI 用户开放新增安装。已安装插件的老用户升级新版 CLI 后仍可继续使用，其他 TS 版本 CLI 用户暂不支持安装。</p></div><h2 id="打开面板" tabindex="-1">打开面板 <a class="header-anchor" href="#打开面板" aria-label="Permalink to “打开面板”">​</a></h2><p><img src="/code/docs/images/zh/vscode/kimi-code-command-palette.png" alt="Kimi Code Command Palette"></p><p>点击活动栏中的 Kimi 图标，或通过命令面板执行 &quot;Kimi Code&quot; 命令。</p><hr><h1 id="输入与控制" tabindex="-1">输入与控制 <a class="header-anchor" href="#输入与控制" aria-label="Permalink to “输入与控制”">​</a></h1><h2 id="文件引用" tabindex="-1">文件引用 <a class="header-anchor" href="#文件引用" aria-label="Permalink to “文件引用”">​</a></h2><p>输入 <code>@</code> 后选择文件或文件夹名称。例如：<code>@src/handlers/</code> 引用文件夹，<code>@app.ts</code> 引用文件，<code>@src/app.ts:10-20</code> 引用特定行范围。</p><p>按 <code>Alt+K</code> 可快速插入当前文件或选中代码作为引用。</p><h2 id="斜杠命令" tabindex="-1">斜杠命令 <a class="header-anchor" href="#斜杠命令" aria-label="Permalink to “斜杠命令”">​</a></h2><p>输入 <code>/</code> 打开命令菜单。使用 <code>/init</code> 扫描项目并生成文档，或使用 <code>/compact</code> 压缩过长的上下文。</p><h2 id="输入历史" tabindex="-1">输入历史 <a class="header-anchor" href="#输入历史" aria-label="Permalink to “输入历史”">​</a></h2><p>在输入框中按 <code>↑</code> / <code>↓</code> 键可快速浏览最近发送过的消息历史，方便重复或修改提问。</p><h2 id="媒体文件输入" tabindex="-1">媒体文件输入 <a class="header-anchor" href="#媒体文件输入" aria-label="Permalink to “媒体文件输入”">​</a></h2><p>支持粘贴、拖拽或选择媒体文件。支持的格式包括：PNG、JPEG、GIF、WebP、HEIC 等图片格式，以及 MP4、WebM、MOV 等视频格式。</p><ul><li><strong>粘贴 / 拖拽</strong>：单张图片原始大小不超过 5MB，系统会自动进行压缩（HEIC 转 JPEG、超尺寸缩放、质量压缩至约 2MB）。</li><li><strong>文件选择器</strong>：通过输入框的 &quot;+&quot; 按钮或 <code>@</code> 菜单选择文件时，图片不超过 10MB，视频不超过 20MB。</li><li><strong>通用限制</strong>：每条消息最多附加 9 个文件，总计不超过 80MB。当附加媒体文件时，不支持多模态的模型将被自动过滤。</li></ul><h2 id="消息队列" tabindex="-1">消息队列 <a class="header-anchor" href="#消息队列" aria-label="Permalink to “消息队列”">​</a></h2><p>当 Kimi 正在回复时，你可以在输入框中继续输入并发送。这些消息不会丢失，而是会进入<strong>消息队列</strong>。底部工具栏会显示队列数量，点击可展开队列面板：</p><ul><li>查看待发送的消息列表</li><li>编辑或删除队列中的消息</li><li>调整消息顺序</li><li>在 Kimi 回复过程中，点击队列项的 ⚡ 图标可将该消息立即作为 <strong>Steer</strong> 插入，引导 Kimi 调整当前回复方向</li></ul><h2 id="模型切换" tabindex="-1">模型切换 <a class="header-anchor" href="#模型切换" aria-label="Permalink to “模型切换”">​</a></h2><p>通过输入栏下拉菜单切换模型。</p><p><strong>使用高速版</strong>：高速版（<code>kimi-for-coding-highspeed</code>）输出速度约为普通版的 5–6 倍、额度消耗约为普通版的 3 倍，需订阅 <a href="https://www.kimi.com/membership/pricing?from=kfc_membership_topbar&amp;track_id=a7764d49-73ad-4d08-b2f3-a8d7433917f8" target="_blank" rel="noreferrer">Allegretto</a> 及以上档位会员。若模型下拉中还没有高速版，<strong>重启 VS Code 或重新安装插件</strong>即可，之后在下拉菜单里选择 <code>kimi-for-coding-highspeed</code> 使用高速版。</p><h2 id="深度思考模式" tabindex="-1">深度思考模式 <a class="header-anchor" href="#深度思考模式" aria-label="Permalink to “深度思考模式”">​</a></h2><p>部分模型支持扩展推理能力。思考模式切换有两种状态：模型不支持思考模式时隐藏、用户可手动启用/禁用。</p><blockquote><p><strong>注意</strong>：调用最新的 <strong>K2.7 Code</strong> 模型必须开启思考模式（Thinking），否则请求会被路由到旧版模型。</p></blockquote><p>启用后，思考步骤在响应中默认折叠，可展开查看推理过程。在设置中开启 <code>kimi.alwaysExpandThinking</code> 可默认展开思考过程。</p><hr><h1 id="工作模式" tabindex="-1">工作模式 <a class="header-anchor" href="#工作模式" aria-label="Permalink to “工作模式”">​</a></h1><h2 id="操作确认与工具执行" tabindex="-1">操作确认与工具执行 <a class="header-anchor" href="#操作确认与工具执行" aria-label="Permalink to “操作确认与工具执行”">​</a></h2><p>当 Kimi 提议运行工具或写入文件时，将显示确认对话框，提供三个选项：</p><ul><li><strong>Yes</strong>：仅批准当前操作</li><li><strong>Yes, for this session</strong>：批准当前会话内同类操作，直至开启新会话</li><li><strong>No</strong>：拒绝执行操作</li></ul><p>在设置中启用 <code>kimi.yoloMode</code> 可自动批准所有工具调用。适用于信任工作流程且追求效率的场景。</p><h3 id="问答弹窗-question-dialog" tabindex="-1">问答弹窗（Question Dialog） <a class="header-anchor" href="#问答弹窗-question-dialog" aria-label="Permalink to “问答弹窗（Question Dialog）”">​</a></h3><p>在执行过程中，Kimi 可能会向你提出问题（例如让你选择实现方案）。此时底部会弹出问答卡片，你可以直接点选预设选项，或选择 &quot;Custom response...&quot; 输入自定义回复。回答后 Kimi 会继续执行。</p><h2 id="计划模式-plan-mode" tabindex="-1">计划模式（Plan Mode） <a class="header-anchor" href="#计划模式-plan-mode" aria-label="Permalink to “计划模式（Plan Mode）”">​</a></h2><p>点击输入框左侧的 📋 图标可进入计划模式。开启后，Kimi 在正式执行前会先输出一个可展开的计划卡片（Plan Card），列出它打算执行的步骤。你可以审阅计划后再让它继续。</p><ul><li>计划模式按钮在每次新会话时保持上次的设置。</li><li>如果 Kimi 已经在流式回复中，退出计划模式需要二次确认，以免打断当前任务。</li></ul><h2 id="文件变更追踪" tabindex="-1">文件变更追踪 <a class="header-anchor" href="#文件变更追踪" aria-label="Permalink to “文件变更追踪”">​</a></h2><p>Kimi 修改文件后，所有变更将被追踪并显示在&quot;文件变更&quot;栏中。您可以查看被修改文件的列表及其状态（新增、修改或删除），以及增删行数统计。</p><p>针对每个文件，您可在 VS Code 原生 diff 视图中查看变更、恢复至原始状态，或保留变更以清除追踪记录。支持批量操作，可一次性保留或撤销所有变更。基准状态在会话中首次修改时捕获，回退将恢复至此基准版本。</p><hr><h1 id="上下文管理" tabindex="-1">上下文管理 <a class="header-anchor" href="#上下文管理" aria-label="Permalink to “上下文管理”">​</a></h1><h2 id="历史会话" tabindex="-1">历史会话 <a class="header-anchor" href="#历史会话" aria-label="Permalink to “历史会话”">​</a></h2><p>点击面板顶部的历史下拉菜单可浏览过往会话。会话数据本地存储，支持关键词搜索。您可删除旧会话或加载会话以继续之前的对话。</p><p>状态栏显示上下文使用百分比及输入输出 token 计数。当上下文使用率较高时，请使用 <code>/compact</code> 命令进行压缩。</p><h2 id="工作目录切换" tabindex="-1">工作目录切换 <a class="header-anchor" href="#工作目录切换" aria-label="Permalink to “工作目录切换”">​</a></h2><p>点击输入框右侧的齿轮图标（Action Menu）→ <strong>Working Directory</strong>，可以在当前 Workspace 的不同子目录间切换工作目录。切换后会自动开启新会话，以便 Kimi 基于新的目录上下文工作。支持直接选择已注册的子目录，或通过 &quot;Browse...&quot; 浏览任意子文件夹。</p><hr><h1 id="操作菜单" tabindex="-1">操作菜单 <a class="header-anchor" href="#操作菜单" aria-label="Permalink to “操作菜单”">​</a></h1><h2 id="操作菜单-action-menu" tabindex="-1">操作菜单（Action Menu） <a class="header-anchor" href="#操作菜单-action-menu" aria-label="Permalink to “操作菜单（Action Menu）”">​</a></h2><p>输入框右侧的齿轮图标是操作菜单入口，包含以下功能：</p><ul><li><strong>Working Directory</strong>：切换当前工作目录（详见上文&quot;工作目录切换&quot;）</li><li><strong>MCP Servers</strong>：打开 MCP 服务器配置面板</li><li><strong>General Config</strong>：打开 VS Code 设置中的 Kimi 配置页</li><li><strong>Show Logs</strong>：打开 Kimi Code 输出日志面板，便于排查问题</li><li><strong>Reset Kimi</strong>：重置 Kimi Webview，适用于界面卡死或无响应的情况</li><li><strong>Sign out / Sign in</strong>：登出或重新登录 Kimi 账号</li></ul><p>此外，你也可以在 VS Code 命令面板中执行 &quot;Kimi Code: Run CLI&quot;，在集成终端中直接启动 Kimi Code CLI。</p>`,54)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};